import{_ as t,o as p,c as e,a3 as l}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/51-去激活策略.md","filePath":"books/attached/51-去激活策略.md","lastUpdated":1794298621000}'),i={name:"books/attached/51-去激活策略.md"};function o(_,a,r,s,d,n){return p(),e("div",null,[...a[0]||(a[0]=[l('<h3 id="去激活策略" tabindex="-1">去激活策略 <a class="header-anchor" href="#去激活策略" aria-label="Permalink to &quot;去激活策略&quot;">​</a></h3><p>虽然说麦克、卡拉、斯塔夫罗斯和汤姆在逃避伴侣上所采用的方法各有不同，但他们都无一例外地使用了去激活策略。所谓去激活策略，就是指一系列遏制亲密感发生的行为或思维。这一类策略会大大压抑我们的依恋机制，压抑这种处于我们大脑内部的生物性机制，而因为如此，我们减弱了对于爱恋之人的亲密需求。还记得前面提到的那些实验结果吗？回避型人群并不是没有亲密需求的，只是因为他们下意识地把这种需求遏制下去。而去激活策略，正是日复一日地将这些亲密需求压制下去的绝佳法宝。</p><p>仔细看看下面的去激活策略清单，你就会发现，越是频繁地使用这类策略，就越容易在恋爱中感到孤单和痛苦。</p><p>常用的去激活策略</p><ul><li><p>即使在一起好几年了，还是常常感觉到没有准备好和伴侣定下来。</p></li><li><p>总是会将伴侣的小缺陷扩大，比如对方的说话方式、穿衣品味、吃相等等，甚至会感觉这些小缺陷影响了你对于恋爱的情致。</p></li><li><p>在分手后总也忘不掉前任（稍后会详述这种“幽灵般”的前任情况）。</p></li><li><p>会与他人调情，而这正是导致亲密关系失去安全感的一个很有杀伤力的方法。</p></li><li><p>不愿说“我爱你”，而这往往表示你对他还有感觉。</p></li><li><p>在恋情发展很顺利时，突然把他推开，比如在一次很浪漫的约会之后，几天都不再给对方一个电话。</p></li><li><p>会产生一些没有未来的爱恋，比如恋上已婚人士。</p></li><li><p>对伴侣保留自己的小秘密，通过保持神秘来捍卫自己的独立性。</p></li><li><p>抗拒身体接触，比如不愿和伴侣同床、抗拒性生活，与伴侣同行的时候也会保持几步之遥。</p></li></ul><p>回避型依恋风格的人群，总会下意识地在日常生活中，采用这些去激活策略，以此来防止伴侣（或潜在伴侣）挑战自己的权威。但是假以时日，这些小伎俩反而会让你在恋爱时倍感痛苦。</p>',6)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
